INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 10, 'theory', 'Квиз: мосты, veth, VLAN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 0, 'В выводе ip -d link у моста указано ageing_time 30000. Сколько это по времени?', '["30 секунд", "300 секунд", "30000 секунд", "8,3 часа"]', 1, 'Времена моста в ip -d link выводятся в сотых долях секунды, поэтому 30000 это 300 секунд, значение по умолчанию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 1, 'Кадр с неизвестным юникаст-адресом получателя пришёл на порт p2 моста, у которого четыре порта в состоянии forwarding. Что сделает мост?', '["Отбросит кадр", "Отправит его обратно на p2", "Разошлёт на p1, p3 и p4", "Разошлёт на все четыре порта, включая p2"]', 2, 'Неизвестный юникаст рассылается во все остальные порты в состоянии пересылки; обратно в порт-источник мост кадр не отправляет. Адрес отправителя при этом запоминается за p2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 2, 'Что верно про старение динамических записей FDB?', '["Таймер записи перезапускается кадрами, пришедшими от этого адреса как отправителя", "Таймер перезапускается каждым кадром, отправленным на этот адрес", "Записи не стареют, пока порт включён", "Записи стареют через 15 секунд, как состояния STP"]', 0, 'Мост обновляет запись, когда видит адрес как отправителя. Пересылка кадров получателю таймер не сдвигает, так что молчащий хост через ageing_time (по умолчанию 300 с) забывается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 3, 'Мост с vlan_filtering 1. На порту без PVID приходит кадр без тега. Что произойдёт?', '["Кадр попадёт во VLAN 1", "Кадр будет разослан по всем VLAN", "Кадр пройдёт без изменений, как без фильтрации", "Кадр будет отброшен"]', 3, 'Кадр без тега относят к PVID порта. Если PVID не задан, отнести его некуда, и мост его отбрасывает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 4, 'Что верно про подинтерфейс eth0.100, созданный командой ip link add link eth0 name eth0.100 type vlan id 100?', '["Номер VLAN берётся из имени, поэтому id указывать необязательно", "Его MTU сначала равен MTU родителя и не может быть больше", "Он принимает кадры любого VLAN и снимает тег", "Он работает, только если eth0 входит в мост"]', 1, 'Номер задаёт параметр id, имя лишь соглашение. MTU подинтерфейса не превышает родительский, а тег добавляет 4 байта к кадру в проводе.');
